INSERT INTO oc_lab_sample (id, act_no, batch_id, azs_code, tank_code, product_code, sample_point, operator_name, status, volume_ml, seal_no, note) VALUES (gen_random_uuid(), 'АОП-' || to_char(NOW(),'YYYYMMDD-HH24MISS') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,4), (SELECT b.batch_id FROM oc_batch b WHERE b.batch_id = NULLIF(?, '') LIMIT 1), NULLIF(?, ''), NULLIF(?, ''), COALESCE(NULLIF(?, ''), 'АИ-92'), COALESCE(NULLIF(?, ''), 'РГС'), COALESCE(NULLIF(?, ''), '-'), 'sampled', CASE WHEN COALESCE(?, '') ~ '^[0-9]+([.][0-9]+)?$' THEN ?::double precision ELSE 1000 END, NULLIF(?, ''), COALESCE(NULLIF(?, ''), ''))
